<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { onPullDownRefresh, onShareAppMessage, onShow, onHide } from '@dcloudio/uni-app';
import GalleryMobile from '../../components/GalleryMobile.vue';
import ShopMobile from '../../components/ShopMobile.vue';
import CheckinMobile from '../../components/CheckinMobile.vue';
import ForumMobile from '../../components/ForumMobile.vue';
import CommunityMobile from '../../components/CommunityMobile.vue';
import ChatMobile from '../../components/ChatMobile.vue';
import WeatherMobile from '../../components/WeatherMobile.vue';
import { useChatUnread } from '../../../../shared/useChat';
import SupportMobile from '../../components/SupportMobile.vue';
import EngagementMobile from '../../components/EngagementMobile.vue';
import MobileAds from '../../components/MobileAds.vue';
import { forumEnabled } from '../../../../shared/features';
import { api, getToken, setToken } from '../../platform';
import { type Row, eventCategories, postCategories, statusNames, roleNames, newProfile, privacy, agreement, formatTime, eventState } from '../../../../shared/domain';
const checkinTarget = ref<Row | null>(null);
function beginCheckin(row: Row) { checkinTarget.value = row;go('checkin'); }
const chatTarget = ref<Row | null>(null);
const foreground = ref(true);
onShow(() => { foreground.value = true; });
onHide(() => { foreground.value = false; });
function chatMember(member: Row) { chatTarget.value = member;go('chat'); }
const contactTarget = ref<Row | null>(null);
function contactMember(member: Row) { contactTarget.value = member;go('contacts'); }
const tab = ref('home'), screen = ref(''), form = ref<Row>({}), user = ref<Row | null>(null), selected = ref<Row>({});
const stats = ref<Row>({}), events = ref<Row[]>([]), posts = ref<Row[]>([]), notices = ref<Row[]>([]), members = ref<Row[]>([]), signups = ref<Row[]>([]), ownPosts = ref<Row[]>([]);
const error = ref(''), busy = ref(false), loading = ref(false), filter = ref('全部'), search = ref('');
const { unread } = useChatUnread(() => user.value, api);
const approved = computed(() => user.value?.status === 'approved');
const listEvents = computed(() => events.value.filter(e => (filter.value === '全部' || e.category === filter.value) && (e.title + e.location).includes(search.value)));
const listPosts = computed(() => posts.value.filter(p => (filter.value === '全部' || p.category === filter.value) && (p.title + p.content).includes(search.value)));
const visibleMembers = computed(() => members.value.filter(m => [m.name, m.hometown, m.district, m.industry].join(' ').includes(search.value)));
const hours = computed(() => signups.value.reduce((sum, s) => sum + Number(s.hours || 0), 0));
let loadGeneration = 0;
function fail(e: any) { error.value = e?.message || '操作失败，请稍后重试'; }
function toggle(key: string, event: any) { form.value[key] = Boolean(event.detail.value); }
function toast(title: string) { uni.showToast({ title, icon: 'none', duration: 2500 }); }
function expired() { ++loadGeneration; loading.value = false; user.value = null; contactTarget.value = null; chatTarget.value = null; signups.value = []; ownPosts.value = []; members.value = []; events.value = []; posts.value = []; notices.value = []; selected.value = {}; form.value = {}; screen.value = ''; }
async function load() {
  const generation = ++loadGeneration;
  const current = () => generation === loadGeneration;
  loading.value = true;
  try { if (user.value) { const me = await api('/auth/me'); if (!current()) return; user.value = me; if (me.mustChangePassword) { open('password', { oldPassword: '', newPassword: '' }); return; } }
    const data = await Promise.all([api('/home'), api('/events'), api('/posts'), api('/notices')]); if (!current()) return; [stats.value, events.value, posts.value, notices.value] = data;
    if (user.value && !user.value.mustChangePassword) { const data = await Promise.all([api('/my/signups'), api('/my/posts')]); if (!current()) return; [signups.value, ownPosts.value] = data; if (tab.value === 'directory' && approved.value) { const rows = await api('/members'); if (!current()) return; members.value = rows; } }
  } catch (e) { if (current()) fail(e); } finally { if (current()) loading.value = false; }
}
function open(kind: string, data: Row = {}) { error.value = ''; screen.value = kind; form.value = { ...data }; uni.pageScrollTo({ scrollTop: 0, duration: 0 }); }
async function go(id: string) { if (id !== 'checkin') checkinTarget.value = null; if (id !== 'chat') chatTarget.value = null; if (id !== 'contacts') contactTarget.value = null; screen.value = ''; tab.value = id; filter.value = '全部'; search.value = ''; error.value = ''; uni.pageScrollTo({ scrollTop: 0, duration: 0 }); if (user.value?.mustChangePassword) return open('password', { oldPassword: '', newPassword: '' }); await load(); }
function join() { user.value ? go('account') : open('register', newProfile()); }
function needMember() { if (!user.value) { open('login', { username: '', password: '' }); return false; } if (!approved.value) { go('account'); toast('入会审核通过后即可参与'); return false; } return true; }
async function act(action: () => Promise<any>, text: string) { if (busy.value) return; ++loadGeneration; loading.value = false; busy.value = true; error.value = ''; try { await action(); screen.value = ''; toast(text); if (user.value?.mustChangePassword) open('password', { oldPassword: '', newPassword: '' }); else await load(); } catch (e) { fail(e); } finally { busy.value = false; } }
async function authSubmit() { await act(async () => { const result = await api('/auth/' + screen.value, 'POST', form.value); user.value = result.user; setToken(result.token); tab.value = 'account'; }, screen.value === 'register' ? '已提交入会申请' : '欢迎回家'); }
function detail(kind: string, data: Row) { selected.value = data; open(kind); }
function signup() { if (needMember()) act(() => api('/events/' + selected.value.id + '/signup', 'POST'), '报名成功，期待相见'); }
function post() { if (needMember()) open('post', { title: '', category: '生活互助', content: '', contact: '' }); }
function confirm(path: string, content: string) { uni.showModal({ title: '请确认', content, success: result => { if (result.confirm) act(() => api(path, 'POST'), '操作已完成'); } }); }
function phone() { uni.makePhoneCall({ phoneNumber: '13862597517' }); }
onMounted(async () => { uni.$on('session-expired', expired); if (getToken()) { try { user.value = await api('/auth/me'); } catch (e) { fail(e); } } if (user.value?.mustChangePassword) open('password', { oldPassword: '', newPassword: '' }); else await load(); });
onUnmounted(() => uni.$off('session-expired', expired));
onPullDownRefresh(async () => { await load(); uni.stopPullDownRefresh(); });
onShareAppMessage(() => ({ title: '沭阳之家 · 乡情相聚，守望相助', path: '/pages/index/index' }));
</script>

<template>
  <view class="page">
    <view v-if="error" class="error"><text>{{ error }}</text><button class="text-button" @click="load">重新加载</button></view>
    <view v-if="loading" class="loading">正在加载家里的消息…</view>
    <template v-if="!screen">
      <template v-if="tab === 'home'"><view class="row"><view><view class="title">在苏州，也在家。</view><view class="intro">一份乡情，一生牵挂。</view></view><image src="/static/logo.png" class="logo" mode="aspectFit"/></view><view class="hero"><text class="hero-mark">SHUYANG HOME / 欢迎回家</text><text class="hero-title">把日子过好，<br/>和老乡<text>一起。</text></text><view class="muted">赴一场相聚，分享一份所长。<br/>把他乡的日常，慢慢过成家的模样。</view><button @click="join">{{ user ? '查看我的会员卡 →' : '加入沭阳之家 →' }}</button></view><WeatherMobile/><view class="shortcuts"><button @click="go('gallery')">相聚相册<text>留住美好时光</text></button><button @click="go('shop')">家乡特产<text>捎一份乡情</text></button><button @click="go('checkin')">签到／扫一扫<text>到场打个招呼</text></button></view><view class="shortcuts"><button @click="go('events')">乡情活动<text>一起走出屏幕</text></button><button @click="go('directory')">老乡名录<text>遇见家乡的人</text></button><button @click="go('events'); filter = '公益志愿'">公益志愿<text>把温暖传下去</text></button></view><view class="shortcuts"><button v-if="forumEnabled" @click="go('forum')">老乡论坛<text>分享经验，聊聊家常</text></button><button @click="go('resources')">资源互换<text>你有所长，我有所需</text></button><button @click="go('polls')">会员投票<text>一起商量决定</text></button><button @click="go('ads')">合作广告<text>审核后展示</text></button></view><view class="shortcuts"><button @click="go('crowdfunding')">爱心众筹<text>汇聚每份支持</text></button><button @click="go('contacts')">联系方式交换<text>双方同意后分享</text></button></view><view class="home-chat-link" @click="go('chat')"><view><text class="home-chat-symbol">聊</text></view><view><view>家里聊聊</view><text>{{ unread ? unread + '条新消息在等你' : '一句问候，拉近彼此' }}</text></view><text>↗</text></view><MobileAds placement="home"/><view class="row"><view class="section-title">下一场，与老乡相聚</view><button class="text-button" @click="go('events')">全部 →</button></view><view v-if="!events.some(e => e.status === 'published')" class="empty">下一场相聚，正在酝酿。<br/>志愿团队发布活动后，你可以在这里报名。</view><view v-for="event in events.filter(e => e.status === 'published').slice(0, 2)" :key="event.id" class="panel" @click="detail('event', event)"><view class="row"><text class="tag">{{ event.category }}</text><text class="muted">{{ eventState(event) }}</text></view><text class="card-title">{{ event.title }}</text><view class="meta">{{ event.location }}</view><text class="event-time">{{ formatTime(event.startsAt) }} · 北京时间</text></view><view class="row"><view class="section-title">家里有新消息</view><button class="text-button" @click="go('notices')">全部 →</button></view><view class="panel welcome">不问身份，不设门槛。<br/>乡音，就是我们的暗号。<button class="text-button" @click="go('about')">认识沭阳之家 →</button></view><view class="stats"><view><text class="hours">{{ stats.members ?? '—' }}</text><text class="stat-label">已加入的家人</text></view><view><text class="hours">{{ stats.events ?? '—' }}</text><text class="stat-label">已发布的活动</text></view><view><text class="hours">{{ stats.volunteerHours ?? '—' }}</text><text class="stat-label">志愿服务 / 小时</text></view></view></template>
      <GalleryMobile v-if="tab === 'gallery'" :user="user"/><ShopMobile v-if="tab === 'shop'" :user="user" @join="join"/><CheckinMobile v-if="tab === 'checkin'" :user="user" :target="checkinTarget" @join="join"/><ChatMobile v-if="tab === 'chat'" :user="user" :target="chatTarget" :foreground="foreground" @clear-target="chatTarget = null" @join="join"/><SupportMobile v-if="tab === 'crowdfunding' || tab === 'contacts'" :mode="tab === 'crowdfunding' ? 'crowdfunding' : 'contacts'" :user="user" :target="contactTarget" @clear-target="contactTarget = null" @join="join"/><EngagementMobile v-if="tab === 'ads' || tab === 'polls'" :mode="tab === 'ads' ? 'ads' : 'polls'" :user="user" @join="join"/><ForumMobile v-if="tab === 'forum'" :user="user" @join="join"/><CommunityMobile v-if="tab === 'resources'" mode="resources" :user="user" @join="join"/><template v-if="tab === 'events'"><view class="title">相聚，总有好时光</view><EngagementMobile mode="activities" :user="user" @join="join" @updated="load"/><MobileAds placement="events"/><view class="intro">喝杯茶，聊聊天；走出屏幕，见见老乡。</view><view class="pill-row"><text v-for="category in ['全部', ...eventCategories]" :key="category" :class="['pill', { active: filter === category }]" @click="filter = category">{{ category }}</text></view><input v-model="search" class="search" placeholder="搜索活动、地点" maxlength="80"/><view v-if="!listEvents.length" class="empty">暂时没有匹配的活动<br/>欢迎常回来看看</view><view v-for="event in listEvents" :key="event.id" class="panel" @click="detail('event', event)"><view class="row"><text class="tag">{{ event.category }}</text><text class="muted">{{ eventState(event) }}</text></view><text class="card-title">{{ event.title }}</text><view class="meta">{{ formatTime(event.startsAt) }} · 北京时间</view><view class="meta">{{ event.location }}</view><view class="post-excerpt">{{ event.description }}</view><view class="card-actions"><text class="muted">{{ event.registered }}/{{ event.capacity }} 人报名</text><text class="link">{{ event.mySignup ? '已报名 · 查看' : '查看详情 →' }}</text></view></view></template>
      <template v-if="tab === 'community'"><view class="title">有事搭把手，都是自家人</view><view class="intro">互通有无，守望相助。</view><button class="primary" @click="post">＋ 发布互助信息</button><view class="divider"/><view class="pill-row"><text v-for="category in ['全部', ...postCategories]" :key="category" :class="['pill', { active: filter === category }]" @click="filter = category">{{ category }}</text></view><input v-model="search" class="search" placeholder="搜索互助信息" maxlength="80"/><view v-if="!listPosts.length" class="empty">第一份互助，从你开始。<br/>分享一个机会，或说出你的需要。</view><view v-for="item in listPosts" :key="item.id" class="panel" @click="detail('postDetail', item)"><text class="tag">{{ item.category }}</text><text class="card-title">{{ item.title }}</text><view class="post-excerpt">{{ item.content }}</view><view class="card-actions"><text class="muted">{{ item.authorName }}</text><text class="link">查看详情 →</text></view></view></template>
      <template v-if="tab === 'directory'"><view class="title">在苏州，遇见家乡人</view><view class="intro">仅展示自愿公开资料的会员。</view><view v-if="!approved" class="empty">名录仅对已审核会员开放<button class="primary" @click="join">{{ user ? '查看入会状态' : '申请加入' }}</button></view><template v-else><input v-model="search" class="search" placeholder="姓名、家乡、行业" maxlength="80"/><view v-if="!visibleMembers.length" class="empty">暂时没有公开的会员资料</view><view v-for="member in visibleMembers" :key="member.id" class="panel"><view class="row"><text class="profile-name">{{ member.name }}</text><text v-if="member.volunteer" class="tag">志愿意向</text></view><view class="meta">{{ member.hometown }} · {{ member.district }}</view><view class="meta">{{ member.industry }}</view><view class="prose">{{ member.bio }}</view><view v-if="member.phone" class="notice-line">联系方式：{{ member.phone }}</view><button v-if="member.id !== user?.id" class="primary" @click="chatMember(member)">站内聊聊</button><button v-if="member.id !== user?.id" class="outline" @click="contactMember(member)">申请交换联系方式</button></view></template></template>
      <template v-if="tab === 'notices'"><view class="title">家乡的声音，身边的消息</view><view class="intro">家乡文化 · 平台公告</view><view v-if="!notices.length" class="empty">消息正在路上，敬请期待。</view><view v-for="notice in notices.filter(n => n.status === 'published')" :key="notice.id" class="panel" @click="detail('noticeDetail', notice)"><text class="tag">{{ notice.category }}</text><text class="card-title">{{ notice.title }}</text><view class="post-excerpt">{{ notice.content }}</view><view class="meta">{{ formatTime(notice.createdAt) }}</view></view></template>
      <template v-if="tab === 'about'"><view class="title">远离故土，却不远离家乡</view><view class="intro">以乡音牵起乡愁，以乡情温暖他乡。</view><view class="panel"><view class="prose">苏州沭阳之家由一凡小哥（周学超）发起，扎根苏州，是民间自发组建、无官方注册、不属于社团组织、非商业盈利的乡情交流群体。

面向所有在苏州生活、务工、打拼、创业的沭阳老乡，兼顾普通在外工作者、青年创业者。没有身份高低，没有职位门槛。

乡情交友 · 互助发展 · 信息共享 · 文化传承 · 公益慈善

线下活动地：苏州市木渎镇兵圣路200号。活动场地、水电及基础设施由沭阳老乡陈军无偿公益提供。日常运营及活动服务由热心乡情志愿者义务承担。</view><button class="outline" @click="phone">联系平台：13862597517</button></view><image class="poster" src="/static/introduction.jpg" mode="widthFix"/><view class="panel"><view class="prose">{{ agreement }}</view></view></template>
      <template v-if="tab === 'account'"><view v-if="!user" class="empty"><view class="title">欢迎回家</view><view class="intro">登录后查看会员卡与参与记录</view><button class="primary" @click="open('login', { username: '', password: '' })">登录账号</button><button class="outline" @click="join">申请加入</button></view><template v-else><view class="membership"><view class="row"><image src="/static/logo.png" class="logo" mode="aspectFit"/><text>沭阳之家 · 电子会员卡</text></view><text class="card-name">{{ user.name }}</text><text class="tag">{{ statusNames[user.status] }} · {{ roleNames[user.role] }}</text><view class="divider"/><view class="muted">会员编号</view><text class="member-number">{{ user.memberNo || '审核通过后生成' }}</text></view><view v-if="user.status !== 'approved'" class="notice-line">{{ user.status === 'pending' ? '申请已提交，请等待志愿团队审核。' : '申请已退回：' + user.reviewNote + '。请编辑资料后重新提交。' }}</view><view class="stats"><view><text class="hours">{{ signups.filter(s => s.status !== 'cancelled').length }}</text><text class="stat-label">活动报名</text></view><view><text class="hours">{{ hours }}</text><text class="stat-label">志愿服务 / 小时</text></view><view><text class="hours">{{ ownPosts.length }}</text><text class="stat-label">互助发布</text></view></view><view class="button-row"><button class="outline small" @click="open('profile', { ...newProfile(), ...user })">编辑资料</button><button class="outline small" @click="open('password', { oldPassword: '', newPassword: '' })">修改密码</button><button class="outline small" @click="act(async () => { await api('/auth/logout', 'POST'); setToken(''); expired(); }, '已退出登录')">退出</button></view><view class="button-row"><button class="small" @click="go('directory')">老乡名录</button><button class="small" @click="go('notices')">家乡公告</button><button class="small" @click="go('about')">关于我们</button></view><view v-if="user.role !== 'member'" class="safe-note">会员审核、活动发布与签到等管理操作，请使用沭阳之家电脑或手机网页的管理工作台。</view><view class="button-row"><button v-if="forumEnabled" class="small" @click="go('forum')">我的论坛话题</button><button class="small" @click="go('polls')">会员投票</button><button class="small" @click="go('ads')">广告申请</button><button class="small" @click="go('resources')">我的资源与交换</button></view><view class="button-row"><button class="small" @click="go('crowdfunding')">我的众筹与支持</button><button class="small" @click="go('contacts')">联系方式交换</button></view><view class="section-title">我的活动</view><view v-if="!signups.length" class="empty">还没有报名活动，下一次相聚见。</view><view v-for="row in signups" :key="row.id" class="panel"><text class="tag">{{ statusNames[row.status] }}{{ row.hours ? ' · ' + row.hours + '小时' : '' }}</text><text class="card-title">{{ row.event.title }}</text><view class="meta">{{ formatTime(row.event.startsAt) }} · {{ row.event.location }}</view><button v-if="row.status === 'registered'" class="text-button" @click="confirm('/events/' + row.eventId + '/cancel-signup', '确认取消本次活动报名？')">取消报名</button></view><view class="section-title">我的互助</view><view v-if="!ownPosts.length" class="empty">暂未发布互助信息</view><view v-for="item in ownPosts" :key="item.id" class="panel"><text class="tag">{{ statusNames[item.status] }}</text><text class="card-title">{{ item.title }}</text><view class="meta">{{ item.reviewNote || item.category }}</view><button v-if="item.status !== 'closed'" class="text-button" @click="confirm('/posts/' + item.id + '/close', '确认关闭这条互助信息？')">关闭信息</button></view></template></template>
    </template>
    <template v-else><button class="detail-back" :disabled="busy" @click="screen = ''; error = ''">← 返回</button><view class="form-page">
      <template v-if="screen === 'login'"><view class="form-title">欢迎回家</view><view class="intro">一声乡音，就是回家的路。</view><view class="field"><text class="field-label">手机号 / 管理员账号</text><input v-model="form.username" maxlength="80" placeholder="请输入账号"/></view><view class="field"><text class="field-label">密码</text><input v-model="form.password" password maxlength="128" placeholder="请输入密码"/></view><button class="primary" :disabled="busy" @click="authSubmit">{{ busy ? '正在登录…' : '登录，回家看看' }}</button><button class="text-button" @click="open('register', newProfile())">还没加入？申请入会</button><view class="safe-note">忘记密码请联系平台核实身份：13862597517</view></template>
      <template v-if="screen === 'register' || screen === 'profile'"><view class="form-title">{{ screen === 'register' ? '成为沭阳之家的一员' : '完善我的资料' }}</view><view class="intro">填写一点关于你的信息。默认不公开。</view><view class="field"><text class="field-label">姓名（必填）</text><input v-model="form.name" maxlength="30"/></view><view v-if="screen === 'register'" class="field"><text class="field-label">手机号（必填）</text><input v-model="form.phone" type="number" maxlength="11"/></view><view class="field"><text class="field-label">家乡乡镇（必填）</text><input v-model="form.hometown" maxlength="50" placeholder="如：沭阳 · 沭城街道"/></view><view class="field"><text class="field-label">现居地区（必填）</text><input v-model="form.district" maxlength="50" placeholder="如：苏州 · 吴中区"/></view><view class="field"><text class="field-label">行业 / 职业（选填）</text><input v-model="form.industry" maxlength="50"/></view><view v-if="screen === 'register'" class="field"><text class="field-label">设置密码（至少12位，包含字母和数字）</text><input v-model="form.password" password maxlength="128"/></view><view class="field"><text class="field-label">一句话介绍自己（选填）</text><textarea v-model="form.bio" maxlength="300"/></view><view class="checkbox-row"><text class="switch-label">我愿意参与志愿服务</text><switch :checked="form.volunteer" color="#174d6b" @change="toggle('volunteer', $event)"/></view><view class="checkbox-row"><text class="switch-label">向已审核会员公开名录资料</text><switch :checked="form.directoryVisible" color="#174d6b" @change="toggle('directoryVisible', $event)"/></view><view class="checkbox-row"><text class="switch-label">在公开名录同时展示手机号</text><switch :checked="form.phoneVisible" color="#174d6b" @change="toggle('phoneVisible', $event)"/></view><view class="safe-note">{{ privacy }}</view><view class="safe-note">{{ agreement }}</view><view v-if="screen === 'register'" class="checkbox-row"><text class="switch-label">我已阅读并同意以上隐私说明及参与约定</text><switch :checked="form.consent" color="#174d6b" @change="toggle('consent', $event)"/></view><button class="primary" :disabled="busy" @click="screen === 'register' ? authSubmit() : act(async () => { user = await api('/profile', 'PUT', { ...form, resubmit: user?.status === 'rejected' }); }, '资料已保存')">{{ busy ? '正在提交…' : screen === 'register' ? '提交入会申请' : user?.status === 'rejected' ? '保存并重新申请' : '保存资料' }}</button></template>
      <template v-if="screen === 'password'"><view class="form-title">修改密码</view><view v-if="user?.mustChangePassword" class="notice-line">请先修改管理员设置的初始密码。</view><view class="field"><text class="field-label">原密码</text><input v-model="form.oldPassword" password maxlength="128"/></view><view class="field"><text class="field-label">新密码（至少12位，包含字母和数字）</text><input v-model="form.newPassword" password maxlength="128"/></view><button class="primary" :disabled="busy" @click="act(async () => { const result = await api('/auth/password', 'POST', form); user = result.user; setToken(result.token); }, '密码已更新')">更新密码</button></template>
      <template v-if="screen === 'event'"><text class="tag">{{ selected.category }} · {{ eventState(selected) }}</text><text class="card-title">{{ selected.title }}</text><view class="meta">{{ formatTime(selected.startsAt) }} — {{ formatTime(selected.endsAt) }}（北京时间）</view><view class="meta">{{ selected.location }}</view><view class="prose content-text">{{ selected.description }}</view><view class="meta">{{ selected.registered }}/{{ selected.capacity }}人报名 · 自愿参与</view><button class="primary" :disabled="busy || !!selected.mySignup || eventState(selected) !== '报名中'" @click="signup">{{ selected.mySignup ? '你已报名，期待相见' : eventState(selected) === '报名中' ? '我要报名' : eventState(selected) }}</button><button v-if="selected.mySignup" class="outline" @click="beginCheckin(selected)">地点签到／扫一扫</button></template>
      <template v-if="screen === 'post'"><view class="form-title">发布互助信息</view><view class="field"><text class="field-label">标题（2–80字）</text><input v-model="form.title" maxlength="80"/></view><view class="field"><text class="field-label">分类</text><picker :range="postCategories" @change="form.category = postCategories[Number($event.detail.value)]"><view class="outline small">{{ form.category }} ▾</view></picker></view><view class="field"><text class="field-label">具体内容（10–3000字）</text><textarea v-model="form.content" maxlength="3000" placeholder="说明你的需求或可提供的帮助，请勿在正文填写敏感信息"/></view><view class="field"><text class="field-label">联系方式（选填，仅已审核会员可见）</text><input v-model="form.contact" maxlength="80"/></view><view class="safe-note">内容审核通过后公开展示，请勿发布未经核实的招聘、投资或收费信息。</view><button class="primary" :disabled="busy" @click="act(() => api('/posts', 'POST', form), '已提交审核')">提交审核</button></template>
      <template v-if="screen === 'postDetail' || screen === 'noticeDetail'"><text class="tag">{{ selected.category }}</text><text class="card-title">{{ selected.title }}</text><view class="prose content-text">{{ selected.content }}</view><view class="meta">{{ selected.authorName || '沭阳之家' }} · {{ formatTime(selected.createdAt) }}</view><view v-if="screen === 'postDetail'" class="notice-line">{{ selected.contact ? '联系方式：' + selected.contact : approved ? '发布者未填写联系方式' : '联系方式仅向已审核会员展示' }}</view></template>
      <template v-if="screen === 'privacy'"><view class="form-title">隐私说明与参与约定</view><view class="prose content-text">{{ privacy }}</view><view class="prose content-text">{{ agreement }}</view><view class="muted">版本：2026-10-27</view></template>
    </view></template>
    <view class="footer">沭阳之家 · 因为有你，家更温暖。<button class="text-button" @click="open('privacy')">隐私与参与约定</button></view>
  </view>
  <view class="bottom-nav"><button v-for="item in [{ id: 'home', label: '首页' }, { id: 'events', label: '活动' }, { id: 'community', label: '互助' }, { id: 'account', label: '我的' }, { id: 'chat', label: '消息' }]" :key="item.id" :class="{ active: tab === item.id && !screen }" @click="go(item.id)"><text class="nav-dot"/>{{ item.label }}<text v-if="item.id === 'chat' && unread" class="unread-badge">{{ unread > 99 ? '99+' : unread }}</text></button></view>
</template>
